import pytest

from solution import Sheet


def test_example_from_spec():
    s = Sheet()
    s.set("A1", "2")
    s.set("A2", "=A1*3+1")
    assert s.get("A2") == 7


@pytest.mark.parametrize(
    "formula, expected",
    [
        ("=1+2*3", 7),
        ("=(1+2)*3", 9),
        ("=10-4-3", 3),
        ("=12/3/2", 2.0),
        ("=-3+5", 2),
        ("=2*-3", -6),
        ("=- (2+3)", -5),
        ("=  1 +  2 ", 3),
        ("=1.5+1", 2.5),
        ("=1+1.5", 2.5),
        ("=3/2", 1.5),
        ("=2*2", 4),
        ("=6/3", 2.0),
    ],
)
def test_arithmetic(formula, expected):
    s = Sheet()
    s.set("A1", formula)
    got = s.get("A1")
    assert got == expected
    assert type(got) is type(expected)


def test_empty_reference_counts_as_zero():
    s = Sheet()
    s.set("A1", "=B1+5")
    s.set("A2", "=C3")
    assert s.get("A1") == 5
    assert s.get("A2") == 0


def test_int_float_mixing_types():
    s = Sheet()
    s.set("A1", "2")
    s.set("A2", "0.5")
    s.set("A3", "=A1+A2")
    s.set("A4", "=A1-A1")
    s.set("A5", "=A1*A1")
    assert s.get("A3") == 2.5 and isinstance(s.get("A3"), float)
    assert s.get("A4") == 0 and isinstance(s.get("A4"), int)
    assert s.get("A5") == 4 and isinstance(s.get("A5"), int)


def test_chained_references():
    s = Sheet()
    s.set("A1", "1")
    s.set("A2", "=A1+1")
    s.set("A3", "=A2+1")
    assert s.get("A3") == 3
    s.set("A1", "10")
    assert s.get("A3") == 12


def test_unparseable_formula_is_value_error_and_raw_kept():
    s = Sheet()
    s.set("A1", "=1+")
    assert s.get("A1") == "#VALUE!"
    assert s.raw("A1") == "=1+"
    s.set("A2", "=(1+2")
    assert s.get("A2") == "#VALUE!"
    s.set("A3", "=")
    assert s.get("A3") == "#VALUE!"
    s.set("A4", "=foo(1)")
    assert s.get("A4") == "#VALUE!"


def test_formula_with_unknown_characters_is_value_error():
    s = Sheet()
    s.set("A1", "=1 % 2")
    assert s.get("A1") == "#VALUE!"
