import re
from dataclasses import dataclass

_CELL_NAME = re.compile(r"([A-Z])([1-9][0-9]{0,2})")
_INT = re.compile(r"-?\d+")
_FLOAT = re.compile(r"-?\d+\.\d+")

_FUNCTIONS = ("SUM", "MIN", "MAX", "AVG", "COUNT")

