@dataclass
class _Num:
    value: object


@dataclass
class _Ref:
    key: tuple


@dataclass
class _Range:
    c1: int
    r1: int
    c2: int
    r2: int


@dataclass
class _Neg:
    operand: object


@dataclass
class _Bin:
    op: str
    left: object
    right: object


@dataclass
class _Call:
    name: str
    args: list


def _parse_cell_text(text):
    """Parse 'A1' / '$A$1' etc. into (col, row), or None when out of bounds."""
    m = re.fullmatch(r"\$?([A-Z])\$?([0-9]+)", text)
    col = ord(m.group(1)) - ord("A")
    row = int(m.group(2))
    if row < 1 or row > 999:
        return None
    return col, row


def _tokenize(text):
    tokens = []
    pos = 0
    while pos < len(text):
        m = _TOKEN.match(text, pos)
        if m is None:
            raise _ParseError(text)
        kind = m.lastgroup
        if kind is not None:
            tokens.append((kind, m.group(kind)))
        pos = m.end()
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise _ParseError(op)

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise _ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = _Bin(op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = _Bin(op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return _Neg(self.unary())
        return self.primary()

    def primary(self):
        kind, text = self.take()
