        if raw is None:
            return None
        if not raw.startswith("="):
            return _literal(raw)
        if key in stack:
            # Re-entering a cell that is still being evaluated means a cycle.
            return "#CYCLE!"
        stack.add(key)
        try:
            value = self._eval_formula(raw, memo, stack)
        finally:
            stack.discard(key)
        memo[key] = value
        return value

    def _eval_formula(self, raw, memo, stack):
        try:
            ast = _parse_formula(raw)
        except _ParseError:
            return "#VALUE!"
        value = self._ev(ast, memo, stack)
        return 0 if value is None else value

    def _ev(self, node, memo, stack):
        if isinstance(node, _Num):
            return node.value
        if isinstance(node, _Ref):
            return self._value(node.key, memo, stack)
        if isinstance(node, _Neg):
            v = _numeric(self._ev(node.operand, memo, stack))
            if _is_error(v):
                return v
            if isinstance(v, str):
                return "#VALUE!"
            return -v
        if isinstance(node, _Bin):
            a = _numeric(self._ev(node.left, memo, stack))
            b = _numeric(self._ev(node.right, memo, stack))
            # Left operand's error wins; any error beats text (#VALUE!).
            if _is_error(a):
                return a
            if _is_error(b):
                return b
            if isinstance(a, str) or isinstance(b, str):
                return "#VALUE!"
            if node.op == "+":
                return a + b
            if node.op == "-":
                return a - b
            if node.op == "*":
                return a * b
            if b == 0:
                return "#DIV/0!"
            return a / b
        if isinstance(node, _Call):
            return self._call(node, memo, stack)
        raise TypeError(node)

    def _call(self, node, memo, stack):
        values = []
        for arg in node.args:
            if isinstance(arg, _Range):
                # Ranges: empty and text cells are skipped; the first error wins.
                for row in range(arg.r1, arg.r2 + 1):
                    for col in range(arg.c1, arg.c2 + 1):
                        v = self._value((col, row), memo, stack)
                        if _is_error(v):
                            return v
                        if isinstance(v, (int, float)):
                            values.append(v)
            else:
                v = _numeric(self._ev(arg, memo, stack))
                if _is_error(v):
                    return v
                if isinstance(v, str):
                    return "#VALUE!"
                values.append(v)
        if node.name == "COUNT":
            return len(values)
        if node.name == "SUM":
            return sum(values)
        if node.name == "AVG":
            if not values:
                return "#DIV/0!"
            return sum(values) / len(values)
        # MIN / MAX of nothing is 0; a float anywhere makes the result a float.
        if not values:
            return 0
        result = min(values) if node.name == "MIN" else max(values)
        return float(result) if any(isinstance(v, float) for v in values) else result


ERRORS = ("#DIV/0!", "#VALUE!", "#REF!", "#CYCLE!")


def _is_error(v):
    return isinstance(v, str) and v in ERRORS


def _numeric(v):
    """An empty cell counts as 0 in arithmetic; everything else passes through."""
    return 0 if v is None else v


_REF_RE = re.compile(
    r"(?<![A-Za-z0-9_$#])(" + _CELL + r")(?::(" + _CELL + r"))?(?![0-9A-Za-z_(])"
)


@dataclass
class _Cell:
    abs_col: bool
    col: int
    abs_row: bool
    row: int


def _in_bounds(col, row):
    return 0 <= col <= 25 and 1 <= row <= 999


def _split_ref(text):
    m = re.fullmatch(r"(\$?)([A-Z])(\$?)([0-9]+)", text)
    return _Cell(m.group(1) == "$", ord(m.group(2)) - ord("A"), m.group(3) == "$", int(m.group(4)))


def _fmt(c):
    return f"{'$' if c.abs_col else ''}{chr(ord('A') + c.col)}{'$' if c.abs_row else ''}{c.row}"


def _text_or_ref(c):
    """Text for a single reference, or #REF! when the shifted cell is gone."""
    return "#REF!" if c is None else _fmt(c)


def _range_text(a, b):
    """Text for a range; #REF! as a whole when either corner is gone."""
    if a is None or b is None:
        return "#REF!"
    return f"{_fmt(a)}:{_fmt(b)}"


def _rewrite_refs(raw, on_single, on_range):
    """Rewrite every reference in a formula, leaving all other text untouched.

    on_single(cell) and on_range(first, second) return replacement text.
    """

    def repl(m):
        if m.group(2) is None:
            return on_single(_split_ref(m.group(1)))
        return on_range(_split_ref(m.group(1)), _split_ref(m.group(2)))

    return _REF_RE.sub(repl, raw)

