            dst_col, dst_row = _key(dst)
            dc, dr = dst_col - src_col, dst_row - src_row

            def shift(c):
                col = c.col + (0 if c.abs_col else dc)
                row = c.row + (0 if c.abs_row else dr)
                if not _in_bounds(col, row):
                    return None
                return _Cell(c.abs_col, col, c.abs_row, row)

            raw = _rewrite_refs(
                raw,
                lambda c: _text_or_ref(shift(c)),
                lambda a, b: _range_text(shift(a), shift(b)),
            )
        self.set(dst, raw)

    def insert_rows(self, at, n):
        if not (1 <= at <= 999 and n >= 1):
            raise ValueError("invalid row or count")
        if any(row >= at and row + n > 999 for _, row in self._cells):
            raise ValueError("rows would move past row 999")

        def shift(c):
            row = c.row + n if c.row >= at else c.row
            if not _in_bounds(c.col, row):
                return None
            return _Cell(c.abs_col, c.col, c.abs_row, row)

        moved = {}
        for (col, row), raw in self._cells.items():
            if raw.startswith("="):
                raw = _rewrite_refs(
                    raw,
                    lambda c: _text_or_ref(shift(c)),
                    lambda a, b: _range_text(shift(a), shift(b)),
                )
            moved[(col, row + n if row >= at else row)] = raw
        self._cells = moved

    def delete_rows(self, at, n):
        if not (1 <= at <= 999 and n >= 1):
            raise ValueError("invalid row or count")
        last = at + n - 1

        def inside(row):
            return at <= row <= last

        def single(c):
            if inside(c.row):
                return None
            row = c.row - n if c.row > last else c.row
            return _Cell(c.abs_col, c.col, c.abs_row, row)

        def span(a, b):
            """New corners for a range, or None when every row in it is deleted."""
            lo, hi = sorted((a.row, b.row))
            if at <= lo and hi <= last:
                return None
            new_lo = at if inside(lo) else lo - n if lo > last else lo
            new_hi = at - 1 if inside(hi) else hi - n if hi > last else hi
            top, bottom = (new_lo, new_hi) if a.row <= b.row else (new_hi, new_lo)
            return (
                _Cell(a.abs_col, a.col, a.abs_row, top),
                _Cell(b.abs_col, b.col, b.abs_row, bottom),
