    tokens = []
    pos = 0
    while pos < len(text):
        m = _TOKEN.match(text, pos)
        if m is None:
            raise _ParseError(text)
        kind = m.lastgroup
        if kind is not None:
            tokens.append((kind, m.group(kind)))
        pos = m.end()
    return tokens


