            args = []
            if self.peek() != ("op", ")"):
                args.append(self.arg())
                while self.peek() == ("op", ","):
                    self.take()
                    args.append(self.arg())
            self.expect_op(")")
            return _Call(text, args)
        if (kind, text) == ("op", "("):
            node = self.expr()
            self.expect_op(")")
            return node
